# -*- coding: utf-8 -*-

slides_part3 = [{'id': 17, 'title': 'Production & Media', 'subtitle': 'Quiz Challenge 1 (10 Questions): Vibrations, Tuning Fork, Vacuum & Waves', 'speech': '', 'questions': [{'question': 'Q1. What is the fundamental physical origin of sound demonstrated in Activity 10.1?', 'options': ['Chemical oxidation', 'Mechanical vibrations (periodic to-and-fro motion) of objects', 'Static charge buildup', 'Nuclear fusion'], 'answer': 1, 'hint': 'Halting the vibration stops the sound immediately.', 'explanation': 'Sound is produced by vibrating bodies; halting the vibration immediately stops the sound.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Halting the vibration stops the sound immediately.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Sound is produced by vibrating bodies; halting the vibration immediately stops the sound.']}, {'question': 'Q2. In a tuning fork (Section 10.1.1), what are the two parallel vibrating arms called?', 'options': ['Stems', 'Prongs or tines', 'Flutes', 'Reeds'], 'answer': 1, 'hint': 'The standard U-shaped laboratory instrument features a stem and two prongs.', 'explanation': 'The two vibrating arms of a tuning fork are called prongs or tines.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: The standard U-shaped laboratory instrument features a stem and two prongs.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: The two vibrating arms of a tuning fork are called prongs or tines.']}, {'question': "Q3. What cultural heritage is highlighted in Kongthong village ('Whistling Village') in Meghalaya?", 'options': ['Silent meditation', 'Jingrwai Iawbei: unique whistled or sung tune names assigned to individuals', 'Daily bell ringing', 'Carved stone megaphones'], 'answer': 1, 'hint': 'Mothers compose unique tune names echoing across jungle valleys.', 'explanation': 'Kongthong villagers in Meghalaya use unique whistled tune names (Jingrwai Iawbei) for communication.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Mothers compose unique tune names echoing across jungle valleys.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Kongthong villagers in Meghalaya use unique whistled tune names (Jingrwai Iawbei) for communication.']}, {'question': 'Q4. In the Vacuum Bell Jar experiment (Section 10.2.1), what happens as air is pumped out while the electric bell rings?', 'options': ['The sound gets louder', 'The sound fades gradually until complete silence falls in a vacuum', 'The glass bell jar implodes immediately', 'The bell changes pitch to ultrasound'], 'answer': 1, 'hint': 'Sound requires a material medium to propagate.', 'explanation': 'Sound requires particle collisions; in a vacuum, no sound can propagate.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Sound requires a material medium to propagate.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Sound requires particle collisions; in a vacuum, no sound can propagate.']}, {'question': 'Q5. Why do astronauts on a spacewalk outside the ISS communicate using radio headsets?', 'options': ['Helmets are too tight', 'Outer space is a vacuum and mechanical sound waves cannot travel without a material medium', 'Sound travels too fast in space', 'Radio waves are dangerous'], 'answer': 1, 'hint': 'Radio waves are electromagnetic, while sound is mechanical.', 'explanation': 'Outer space is an acoustic vacuum; astronauts rely on electromagnetic radio signals.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Radio waves are electromagnetic, while sound is mechanical.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Outer space is an acoustic vacuum; astronauts rely on electromagnetic radio signals.']}, {'question': 'Q6. In a longitudinal sound wave (Section 10.3), what are the high-density regions called?', 'options': ['Rarefactions (R)', 'Compressions (C)', 'Crests of light', 'Troughs'], 'answer': 1, 'hint': 'Air particles are crowded together by the forward-moving piston.', 'explanation': 'High-density, high-pressure regions in a longitudinal wave are compressions (C).', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Air particles are crowded together by the forward-moving piston.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: High-density, high-pressure regions in a longitudinal wave are compressions (C).']}, {'question': 'Q7. In a longitudinal sound wave, how do particles of the medium vibrate relative to wave propagation?', 'options': ['Perpendicular to wave direction', 'Parallel to the direction of wave propagation', 'In random circles', 'They do not vibrate'], 'answer': 1, 'hint': 'Contrast with transverse waves where particles vibrate perpendicular.', 'explanation': 'In longitudinal waves, particles vibrate parallel to the axis of wave travel.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Contrast with transverse waves where particles vibrate perpendicular.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: In longitudinal waves, particles vibrate parallel to the axis of wave travel.']}, {'question': 'Q8. In Activity 10.6, why do rice grains dance on a stretched membrane when a metal tray is struck nearby?', 'options': ['Magnetic induction', 'Sound waves transfer mechanical kinetic energy through air pressure oscillations', 'The table tilts', 'Semolina evaporates'], 'answer': 1, 'hint': 'Acoustic waves transfer energy without net transport of matter.', 'explanation': 'Sound waves transfer energy through particle collisions, driving the membrane to vibrate.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Acoustic waves transfer energy without net transport of matter.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Sound waves transfer energy through particle collisions, driving the membrane to vibrate.']}, {'question': 'Q9. What device converts sound waves into electrical signals using a vibrating diaphragm?', 'options': ['Loudspeaker', 'Microphone', 'Prism', 'Battery'], 'answer': 1, 'hint': 'Check Bridging Science and Society in Section 10.4.', 'explanation': 'Microphones transduce acoustic pressure waves into electrical audio signals.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Check Bridging Science and Society in Section 10.4.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Microphones transduce acoustic pressure waves into electrical audio signals.']}, {'question': 'Q10. How does the speed of sound compare across solids, liquids, and gases?', 'options': ['Fastest in gases, slowest in solids', 'Fastest in solids, intermediate in liquids, slowest in gases', 'Equal in all media', 'Fastest in a vacuum'], 'answer': 1, 'hint': 'Dense, rigid media have stronger interatomic elastic forces.', 'explanation': 'Sound travels fastest in solids (~5000 m/s in steel), slower in liquids (~1530 m/s in water), slowest in gases (~344 m/s in air).', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Dense, rigid media have stronger interatomic elastic forces.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Sound travels fastest in solids (~5000 m/s in steel), slower in liquids (~1530 m/s in water), slowest in gases (~344 m/s in air).']}]}, {'id': 18, 'title': 'Wave Parameters', 'subtitle': 'Quiz Challenge 2 (10 Questions): λ, ν, T, Speed Equation & Perception', 'speech': '', 'questions': [{'question': 'Q1. What is the distance between two consecutive compressions or rarefactions called?', 'options': ['Amplitude', 'Wavelength (λ)', 'Time period (T)', 'Frequency (ν)'], 'answer': 1, 'hint': 'Symbolized by Greek letter lambda, measured in meters.', 'explanation': 'Wavelength (λ) is the spatial length of one complete wave cycle between consecutive crests or troughs.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Symbolized by Greek letter lambda, measured in meters.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Wavelength (λ) is the spatial length of one complete wave cycle between consecutive crests or troughs.']}, {'question': 'Q2. If a source completes 20 oscillations in 4 seconds, what are its frequency and time period (Example 10.1)?', 'options': ['ν = 80 Hz, T = 0.0125 s', 'ν = 5 Hz, T = 0.2 s', 'ν = 0.2 Hz, T = 5 s', 'ν = 4 Hz, T = 0.25 s'], 'answer': 1, 'hint': 'ν = oscillations / time = 20 / 4; T = 1 / ν.', 'explanation': 'ν = 20 / 4 = 5 Hz; T = 1 / 5 = 0.2 s.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: ν = oscillations / time = 20 / 4; T = 1 / ν.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: ν = 20 / 4 = 5 Hz; T = 1 / 5 = 0.2 s.']}, {'question': 'Q3. Using the wave equation v = λν, calculate the wavelength in air (v = 344 m/s) for a frequency of 344 Hz:', 'options': ['10 m', '1 m', '0.1 m', '344 m'], 'answer': 1, 'hint': 'λ = v / ν = 344 / 344.', 'explanation': 'λ = 344 / 344 = 1.0 meter.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: λ = v / ν = 344 / 344.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: λ = 344 / 344 = 1.0 meter.']}, {'question': 'Q4. In Example 10.3, thunder is heard 3 seconds after lightning is seen (v = 340 m/s). How far away is the flash?', 'options': ['113 m', '1020 m (1.02 km)', '340 m', '680 m'], 'answer': 1, 'hint': 'Distance = speed × time = 340 × 3.', 'explanation': 'Distance = 340 × 3 = 1020 m = 1.02 km.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Distance = speed × time = 340 × 3.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Distance = 340 × 3 = 1020 m = 1.02 km.']}, {'question': 'Q5. How does the wave energy depend on the amplitude (A) of vibration (Section 10.6.2)?', 'options': ['Energy ∝ 1/A', 'Energy ∝ A² (proportional to square of amplitude)', 'Energy ∝ √A', 'Energy is independent of amplitude'], 'answer': 1, 'hint': 'Doubling amplitude quadruples the energy carried by the wave.', 'explanation': 'Acoustic wave energy is directly proportional to the square of its amplitude: E ∝ A².', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Doubling amplitude quadruples the energy carried by the wave.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Acoustic wave energy is directly proportional to the square of its amplitude: E ∝ A².']}, {'question': 'Q6. What subjective auditory sensation corresponds physically to wave frequency?', 'options': ['Loudness', 'Pitch', 'Timbre', 'Persistence'], 'answer': 1, 'hint': 'High frequency is perceived as shrill; low frequency as deep bass.', 'explanation': "Pitch is the human ear's subjective perception of wave frequency.", 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: High frequency is perceived as shrill; low frequency as deep bass.', 'Step 2: Apply the given acoustic parameters or physical definitions.', "Step 3: Pitch is the human ear's subjective perception of wave frequency."]}, {'question': 'Q7. What is the normal human audible frequency range?', 'options': ['0 to 100 Hz', '20 Hz to 20,000 Hz (20 kHz)', '500 to 50,000 Hz', '20 kHz to 200 kHz'], 'answer': 1, 'hint': 'Frequencies below are infrasound; frequencies above are ultrasound.', 'explanation': 'The human audible range spans from 20 Hz to 20 kHz (20,000 Hz).', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Frequencies below are infrasound; frequencies above are ultrasound.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: The human audible range spans from 20 Hz to 20 kHz (20,000 Hz).']}, {'question': 'Q8. What quality of sound allows us to distinguish two instruments (e.g. flute and violin) playing the same note at the same loudness?', 'options': ['Amplitude', 'Timbre or quality', 'Speed', 'Wavelength'], 'answer': 1, 'hint': 'It depends on the waveform and harmonic overtones.', 'explanation': 'Timbre (or quality) is determined by the harmonic content that gives each instrument its distinctive sound.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: It depends on the waveform and harmonic overtones.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Timbre (or quality) is determined by the harmonic content that gives each instrument its distinctive sound.']}, {'question': 'Q9. What are the three tiny bones (auditory ossicles) in the middle ear called?', 'options': ['Femur, tibia, fibula', 'Hammer, anvil, stirrup (malleus, incus, stapes)', 'Cornea, iris, lens', 'Radius, ulna, carpals'], 'answer': 1, 'hint': 'These three bones amplify vibrations from the eardrum to the oval window.', 'explanation': 'The hammer, anvil, and stirrup (malleus, incus, stapes) transmit and amplify vibrations in the middle ear.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: These three bones amplify vibrations from the eardrum to the oval window.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: The hammer, anvil, and stirrup (malleus, incus, stapes) transmit and amplify vibrations in the middle ear.']}, {'question': 'Q10. In Example 10.4, a sound wave in a steel rod has speed 5000 m/s and wavelength 50 m. What is its frequency?', 'options': ['250,000 Hz', '100 Hz', '50 Hz', '0.01 Hz'], 'answer': 1, 'hint': 'ν = v / λ = 5000 / 50.', 'explanation': 'ν = 5000 / 50 = 100 Hz; time period T = 1/100 = 0.01 s.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: ν = v / λ = 5000 / 50.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: ν = 5000 / 50 = 100 Hz; time period T = 1/100 = 0.01 s.']}]}, {'id': 19, 'title': 'Echoes & Reflection', 'subtitle': 'Quiz Challenge 3 (10 Questions): Reflection, Echo Distance & Reverberation', 'speech': '', 'questions': [{'question': 'Q1. What is the persistence of hearing in the human brain?', 'options': ['1.0 s', '0.1 s (approx. 1/10th of a second)', '0.01 s', '0.5 s'], 'answer': 1, 'hint': 'A separate echo requires sound to return after this minimum delay.', 'explanation': 'Human auditory persistence lasts about 0.1 s; sounds arriving sooner blur with the original sensation.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: A separate echo requires sound to return after this minimum delay.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Human auditory persistence lasts about 0.1 s; sounds arriving sooner blur with the original sensation.']}, {'question': 'Q2. What is the minimum distance to a reflecting obstacle in air (v = 340 m/s) to hear a distinct echo?', 'options': ['3.4 m', '17 m (or 17.2 m at 22°C)', '34 m', '85 m'], 'answer': 1, 'hint': '2d = v × t = 340 × 0.1 = 34 m; divide by 2.', 'explanation': 'Minimum obstacle distance d = (v × t) / 2 = (340 × 0.1) / 2 = 17 meters.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: 2d = v × t = 340 × 0.1 = 34 m; divide by 2.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Minimum obstacle distance d = (v × t) / 2 = (340 × 0.1) / 2 = 17 meters.']}, {'question': 'Q3. In Example 10.5, a person claps and hears an echo after 0.5 s in air (v = 340 m/s). What is the distance to the wall?', 'options': ['170 m', '85 m', '340 m', '42.5 m'], 'answer': 1, 'hint': 'd = (v × t) / 2 = (340 × 0.5) / 2.', 'explanation': 'd = (340 × 0.5) / 2 = 170 / 2 = 85 meters.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: d = (v × t) / 2 = (340 × 0.5) / 2.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: d = (340 × 0.5) / 2 = 170 / 2 = 85 meters.']}, {'question': 'Q4. What is the prolonged persistence of sound due to multiple repeated reflections in large halls called?', 'options': ['Diffraction', 'Reverberation', 'Dispersion', 'Refraction'], 'answer': 1, 'hint': 'Multiple reflections arrive at intervals under 0.05 s, causing words to blur.', 'explanation': 'The repeated reflection of sound that results in persistence of sound is called reverberation.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Multiple reflections arrive at intervals under 0.05 s, causing words to blur.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: The repeated reflection of sound that results in persistence of sound is called reverberation.']}, {'question': 'Q5. Why are ceilings of concert halls and cinema auditoriums usually curved?', 'options': ['To collect rainwater', 'So that reflected sound spreads uniformly across all corners of the auditorium', 'To produce echoes', 'To reduce room volume'], 'answer': 1, 'hint': 'Curved acoustic surfaces reflect sound evenly toward all audience seats.', 'explanation': 'Curved soundboards and ceilings reflect sound waves uniformly across the entire hall.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Curved acoustic surfaces reflect sound evenly toward all audience seats.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Curved soundboards and ceilings reflect sound waves uniformly across the entire hall.']}, {'question': 'Q6. Which historic monument houses the famous Whispering Gallery described in Section 10.7.2?', 'options': ['Taj Mahal, Agra', 'Gol Gumbaz, Vijayapura (Bijapur)', 'Qutub Minar, Delhi', 'Red Fort, Delhi'], 'answer': 1, 'hint': 'A faint whisper circles the massive dome multiple times.', 'explanation': 'Gol Gumbaz in Vijayapura, Karnataka, features a famous Whispering Gallery under its dome.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: A faint whisper circles the massive dome multiple times.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Gol Gumbaz in Vijayapura, Karnataka, features a famous Whispering Gallery under its dome.']}, {'question': 'Q7. What acoustic materials are installed in auditoriums to reduce undesirable reverberation?', 'options': ['Polished marble and glass', 'Compressed fiberboard panels, thick draperies, carpets, and upholstered seats', 'Thin metal sheets', 'Mirrors'], 'answer': 1, 'hint': 'Porous, soft materials absorb acoustic energy rather than reflecting it.', 'explanation': 'Porous acoustic tiles, curtains, carpets, and upholstered chairs absorb sound to control reverberation.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Porous, soft materials absorb acoustic energy rather than reflecting it.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Porous acoustic tiles, curtains, carpets, and upholstered chairs absorb sound to control reverberation.']}, {'question': 'Q8. If an echo returns in 0.8 seconds in air (v = 340 m/s), how far away is the reflecting cliff?', 'options': ['272 m', '136 m', '68 m', '340 m'], 'answer': 1, 'hint': 'd = (340 × 0.8) / 2 = 272 / 2.', 'explanation': 'd = (v × t) / 2 = (340 × 0.8) / 2 = 136 meters.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: d = (340 × 0.8) / 2 = 272 / 2.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: d = (v × t) / 2 = (340 × 0.8) / 2 = 136 meters.']}, {'question': 'Q9. What law of reflection does sound follow when striking a hard surface?', 'options': ['Angle of incidence is greater than angle of reflection', 'Angle of incidence equals angle of reflection (∠i = ∠r)', 'Sound bends at 90 degrees always', 'Sound absorbs completely without reflection'], 'answer': 1, 'hint': 'Sound follows the exact same reflection law as light rays.', 'explanation': 'The angle of incidence equals the angle of reflection (∠i = ∠r), and incident ray, reflected ray, and normal lie in the same plane.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Sound follows the exact same reflection law as light rays.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: The angle of incidence equals the angle of reflection (∠i = ∠r), and incident ray, reflected ray, and normal lie in the same plane.']}, {'question': 'Q10. Why do we NOT hear a separate echo in a small living room with walls 4 meters away?', 'options': ['Sound is destroyed in small rooms', 'The reflected sound returns in less than 0.1 s, merging seamlessly with the original sound', 'Walls have zero density', 'Sound speeds up to light speed'], 'answer': 1, 'hint': 'Round-trip distance 8 m / 340 m/s ≈ 0.024 s, far below 0.1 s.', 'explanation': 'Reflections return in ~0.024 s (well below 0.1 s), blending with original sound without a distinct echo.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Round-trip distance 8 m / 340 m/s ≈ 0.024 s, far below 0.1 s.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Reflections return in ~0.024 s (well below 0.1 s), blending with original sound without a distinct echo.']}]}, {'id': 20, 'title': 'Ultrasound & Sonar', 'subtitle': 'Quiz Challenge 4 (10 Questions): Echolocation, SONAR Calculations & Lithotripsy', 'speech': '', 'questions': [{'question': 'Q1. What frequency range defines ultrasonic waves (ultrasound)?', 'options': ['Below 20 Hz', 'Above 20,000 Hz (20 kHz)', 'Between 20 Hz and 200 Hz', 'Exactly 340 Hz'], 'answer': 1, 'hint': 'Higher than human audible frequency limits.', 'explanation': 'Ultrasound refers to sound waves with frequencies greater than 20 kHz (20,000 Hz).', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Higher than human audible frequency limits.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Ultrasound refers to sound waves with frequencies greater than 20 kHz (20,000 Hz).']}, {'question': 'Q2. How do bats catch flying insects in total darkness using biological echolocation?', 'options': ['They see ultraviolet light', 'They emit high-frequency ultrasonic squeaks and analyze reflected echoes for distance and direction', 'They smell moth pheromones', 'They feel air temperature'], 'answer': 1, 'hint': 'Ultrasound pulses bounce off tiny prey in flight.', 'explanation': 'Bats emit ultrasonic clicks and process the returning echoes to navigate and hunt in the dark.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Ultrasound pulses bounce off tiny prey in flight.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Bats emit ultrasonic clicks and process the returning echoes to navigate and hunt in the dark.']}, {'question': 'Q3. What does the acronym SONAR stand for in marine navigation?', 'options': ['Sound Observation Near Acoustic Radar', 'Sound Navigation and Ranging', 'Submarine Optical Nautical Audio Record', 'Speed Of Nautical Acoustic Radio'], 'answer': 1, 'hint': 'Used for underwater depth sounding and submarine tracking.', 'explanation': 'SONAR stands for Sound Navigation and Ranging.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Used for underwater depth sounding and submarine tracking.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: SONAR stands for Sound Navigation and Ranging.']}, {'question': 'Q4. In Example 10.6, a sonar signal sent from a ship returns after 0.90 s in seawater (v = 1530 m/s). What is the seabed depth?', 'options': ['1377 m', '688.5 m', '344.25 m', '1530 m'], 'answer': 1, 'hint': 'd = (v × t) / 2 = (1530 × 0.90) / 2.', 'explanation': 'd = (1530 × 0.90) / 2 = 1377 / 2 = 688.5 meters.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: d = (v × t) / 2 = (1530 × 0.90) / 2.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: d = (1530 × 0.90) / 2 = 1377 / 2 = 688.5 meters.']}, {'question': "Q5. If a submarine's sonar pulse returns from an underwater reef in 1.2 seconds (v = 1500 m/s), what is the distance to the reef?", 'options': ['1800 m', '900 m', '600 m', '1200 m'], 'answer': 1, 'hint': 'd = (1500 × 1.2) / 2.', 'explanation': 'd = (1500 × 1.2) / 2 = 1800 / 2 = 900 meters.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: d = (1500 × 1.2) / 2.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: d = (1500 × 1.2) / 2 = 1800 / 2 = 900 meters.']}, {'question': 'Q6. In medicine, what technique uses high-frequency ultrasonic pulses to create diagnostic images of internal organs?', 'options': ['X-ray radiography', 'Ultrasonography (ultrasound scanning)', 'Magnetic resonance imaging', 'Electrocardiogram'], 'answer': 1, 'hint': 'Safe for imaging developing fetuses without ionizing radiation.', 'explanation': 'Ultrasonography uses reflected ultrasound waves to image soft tissues and organs.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Safe for imaging developing fetuses without ionizing radiation.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Ultrasonography uses reflected ultrasound waves to image soft tissues and organs.']}, {'question': 'Q7. What medical procedure uses focused high-energy ultrasound to pulverize kidney stones non-invasively?', 'options': ['Chemotherapy', 'Lithotripsy', 'Dialysis', 'Endoscopy'], 'answer': 1, 'hint': 'Check Section 10.8 application list.', 'explanation': 'Ultrasound lithotripsy shatters kidney stones into fine sand-like particles that pass naturally.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Check Section 10.8 application list.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Ultrasound lithotripsy shatters kidney stones into fine sand-like particles that pass naturally.']}, {'question': 'Q8. How is ultrasound utilized in industrial engineering for non-destructive testing?', 'options': ['Melting scrap steel', 'Detecting invisible internal cracks and voids inside metal blocks, aircraft wings, and railway tracks', 'Painting cars', 'Generating electricity'], 'answer': 1, 'hint': 'Ultrasound reflects back early from internal cracks or defects.', 'explanation': 'Internal flaws reflect ultrasonic beams prematurely, pinpointing defects without breaking the metal.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Ultrasound reflects back early from internal cracks or defects.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Internal flaws reflect ultrasonic beams prematurely, pinpointing defects without breaking the metal.']}, {'question': 'Q9. What natural hazard produces deep infrasonic waves (<20 Hz) that can be detected before devastating surface shockwaves arrive?', 'options': ['Solar flares', 'Earthquakes and volcanic eruptions', 'Thunderclaps', 'Aurora borealis'], 'answer': 1, 'hint': 'Low-frequency ground waves propagate long distances.', 'explanation': 'Earthquakes and volcanic tremors generate infrasonic waves used in early warning monitoring.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Low-frequency ground waves propagate long distances.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Earthquakes and volcanic tremors generate infrasonic waves used in early warning monitoring.']}, {'question': 'Q10. What happens when an aircraft flies faster than the speed of sound in air (supersonic flight)?', 'options': ['Sound waves vanish permanently', 'Air pressure shockwaves coalesce to produce an explosive sonic boom', 'The aircraft enters outer space', 'Engines shut down'], 'answer': 1, 'hint': 'Check Ready to Go Beyond in Section 10.3.', 'explanation': 'Breaking the sound barrier creates sharp conical shockwaves heard on the ground as a sonic boom.', 'solution_steps': ['Step 1: Identify the relevant wave principle or formula: Check Ready to Go Beyond in Section 10.3.', 'Step 2: Apply the given acoustic parameters or physical definitions.', 'Step 3: Breaking the sound barrier creates sharp conical shockwaves heard on the ground as a sonic boom.']}]}]
